def count_ways(n, k):
    dp = [[0] * (k + 1) for _ in range(n + 1)]
    dp[0][0] = 1

    for i in range(1, n + 1):
        for j in range(k + 1):
            dp[i][j] = dp[i - 1][j]  # Case where i is not part of any cycle
            if j > 0:
                dp[i][j] = (dp[i][j] + dp[i - 1][j - 1] * (i - 1)) % MOD  # Case where i is part of a cycle

    # Sum up all valid configurations for houses 1 to k
    total_ways = sum(dp[n][j] for j in range(1, k + 1)) % MOD

    # For houses k+1 to n, each house can point to any of the remaining houses
    for i in range(k + 1, n + 1):
        total_ways = (total_ways * (n - i + 1)) % MOD

    return total_ways

